import { useEffect, useRef } from 'react';
import { createPixiApp, resizePixiApp } from '../utils/pixi-config';
import * as PIXI from 'pixi.js';

interface CanvasProps {
  width?: number;
  height?: number;
  backgroundColor?: number;
}

export const Canvas = ({
  width = 800,
  height = 600,
  backgroundColor = 0x1e1e1e,
}: CanvasProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const appRef = useRef<PIXI.Application | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    // Create a new PIXI application if it doesn't exist
    if (!appRef.current) {
      appRef.current = createPixiApp({
        width,
        height,
        backgroundColor,
      });

      // Add the canvas to the container
      containerRef.current.appendChild(appRef.current.view as HTMLCanvasElement);

      // Add a sample sprite to test rendering
      const graphics = new PIXI.Graphics();
      graphics.beginFill(0x5555ff);
      graphics.drawRect(-50, -50, 100, 100);
      graphics.endFill();
      graphics.position.set(width / 2, height / 2);

      appRef.current.stage.addChild(graphics);

      // Simple animation to verify that everything works
      appRef.current.ticker.add(() => {
        graphics.rotation += 0.01;
      });
    }

    // Cleanup function
    return () => {
      if (appRef.current) {
        appRef.current.destroy(true, true);
        appRef.current = null;
      }
    };
  }, [backgroundColor, height, width]);

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      if (appRef.current && containerRef.current) {
        const parent = containerRef.current;
        resizePixiApp(appRef.current, parent.clientWidth, parent.clientHeight);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return <div ref={containerRef} style={{ width, height }} />;
}; 